svg.script:
(function(){
  const correctRing = { r1c2:'ring1', r2c3:'ring2', r3c1:'ring3' };

  function showRing(id){
    const ring = document.getElementById(id);
    ring.classList.remove('show');
    void ring.getBBox();
    ring.classList.add('show');
  }

  document.querySelectorAll('.hit').forEach(function(hit){
    hit.addEventListener('click', function(){
      const target = hit.dataset.target;
      const isCorrect = hit.dataset.correct === 'true';
      const word = document.getElementById(target);

      if(isCorrect){
        showRing(correctRing[target]);
        word.animate(
          [
            { transform:'scale(1)' },
            { transform:'scale(1.035)' },
            { transform:'scale(1)' }
          ],
          { duration:480, easing:'ease-out' }
        );
      }else{
        const w = document.getElementById('wrong-' + target);
        if(w){
          w.classList.remove('show');
          void w.getBBox();
          w.classList.add('show');
        }
        word.animate(
          [
            { transform:'translateX(0)' },
            { transform:'translateX(-3px)' },
            { transform:'translateX(3px)' },
            { transform:'translateX(0)' }
          ],
          { duration:320, easing:'ease-in-out' }
        );
      }
    });
  });

  // إظهار الدوائر الصحيحة بشكل متتابع وواضح.
  setTimeout(function(){ showRing('ring1'); }, 900);
  setTimeout(function(){ showRing('ring2'); }, 1200);
  setTimeout(function(){ showRing('ring3'); }, 1500);
})();
